// expected: CLEAN
// PT9.8 as written: the in-order worker, and the dedupe table kept on archive (K4). delivery_check.py:
// 1,147 states, at-most-once and in-order hold; exactly-once is liveness, checked from M2.
module delivery

type Msg = M1 | M2
type Status = Unsent | Pending | InFlight | Acked

service machine Delivery {
  state {
    status   : map<Msg, Status> = { M1: Unsent, M2: Unsent }
    req      : map<Msg, 0..2>   = { M1: 0, M2: 0 }            // request copies in the network
    ack      : map<Msg, 0..2>   = { M1: 0, M2: 0 }            // acknowledgement copies in the network
    lost     : map<Msg, 0..1>   = { M1: 0, M2: 0 }            // the network loses at most one copy per message
    seen     : map<Msg, bool>   = { M1: false, M2: false }    // the receiver's dedupe table (K4)
    steps    : map<Msg, 0..2>   = { M1: 0, M2: 0 }            // steps taken at the receiver
    archived : bool = false
  }
  action Emit(m: Msg)     action Send(m: Msg)       action Resend(m: Msg)
  action LoseReq(m: Msg)  action DeliverReq(m: Msg) action LoseAck(m: Msg)
  action DeliverAck(m: Msg)  action Archive()

  on Emit(m) {
    require status[m] == Unsent else reject "emitted"
    require m == M1 || status[M1] != Unsent else reject "emit-order"
    status' = status with [m] = Pending
  }
  on Send(m) {
    require status[m] == Pending && req[m] < 2 else reject "not-pending"
    require m == M1 || status[M1] == Acked else reject "in-order"      // the in-order worker
    status' = status with [m] = InFlight
    req' = req with [m] = req[m] + 1
  }
  on Resend(m) {
    require status[m] == InFlight && req[m] < 2 else reject "not-in-flight"
    req' = req with [m] = req[m] + 1
  }
  on LoseReq(m) {
    require req[m] > 0 && lost[m] < 1 else reject "no-loss"
    req' = req with [m] = req[m] - 1
    lost' = lost with [m] = 1
  }
  on DeliverReq(m) {
    require req[m] > 0 else reject "nothing-in-transit"
    req' = req with [m] = req[m] - 1
    if ack[m] < 2 { ack' = ack with [m] = ack[m] + 1 }
    if !seen[m] { seen' = seen with [m] = true
                  steps' = steps with [m] = steps[m] + 1 }
  }
  on LoseAck(m) {
    require ack[m] > 0 && lost[m] < 1 else reject "no-loss"
    ack' = ack with [m] = ack[m] - 1
    lost' = lost with [m] = 1
  }
  on DeliverAck(m) {
    require ack[m] > 0 else reject "no-ack"
    ack' = ack with [m] = ack[m] - 1
    if status[m] == InFlight { status' = status with [m] = Acked }
  }
  on Archive {
    require !archived && steps[M1] == 1 && steps[M2] == 1 else reject "not-done"
    archived' = true                                  // the dedupe table is kept (K4)
  }

  invariant at-most-once: steps[M1] <= 1 && steps[M2] <= 1
  invariant in-order: steps[M2] >= 1 implies steps[M1] >= 1      // M2 never steps before M1 (S64)
  liveness exactly-once:
    eventually (status[M1] == Acked && status[M2] == Acked && steps[M1] == 1 && steps[M2] == 1)
    under fair { Emit(*), Send(*), Resend(*), DeliverReq(*), DeliverAck(*) }
}
// expected: CLEAN
// OutboxIntent in its v0.3 five-field form (03-technical-spec.md at commit 5160ba8).
// evidence/outbox_check.py v0.3: 33 states, 40 accepted steps, no deadlock.
module intents

enum IntentStatus { Pending, Proposed, Allowed, Running, Settled, Denied, Escalated, Dead, Done }

machine OutboxIntent {
  state {
    status    : IntentStatus = Pending
    attempts  : 0..3         = 0
    decisions : 0..2         = 0     // gate decisions taken for this intent
    executed  : bool         = false // the handler may have run (at-least-once)
    approved  : bool         = false
  }
  terminal status in { Done, Denied, Dead }

  action Propose()
  action GateAllow()
  action GateDeny()
  action GateEscalate()
  action Approve()
  action EscalationTimeout()
  action Start()
  action HandlerOk()
  action HandlerFailed()
  action SettleFailed()
  action SettleOk()

  on Propose {
    require status in { Pending } || (status == Escalated && approved) else reject "not-proposable"
    status' = Proposed
    decisions' = decisions + 1
  }
  on GateAllow    { require status == Proposed else reject "no-proposal"   status' = Allowed }
  on GateDeny     { require status == Proposed else reject "no-proposal"
                    require !executed          else reject "deny-after-execution"
                    status' = Denied }
  on GateEscalate { require status == Proposed else reject "no-proposal"
                    require decisions == 1     else reject "escalate-once"
                    status' = Escalated }
  on Approve      { require status == Escalated else reject "not-escalated" approved' = true }
  on EscalationTimeout { require status == Escalated && !approved else reject "not-waiting"
                         status' = Denied }
  on Start        { require status == Allowed  else reject "not-allowed"
                    require attempts < 3       else reject "exhausted"
                    status' = Running
                    attempts' = attempts + 1
                    executed' = true }
  on HandlerOk    { require status == Running  else reject "not-running"   status' = Settled }
  on HandlerFailed { require status == Running else reject "not-running"
                     if attempts < 3 { status' = Allowed } else { status' = Dead } }
  on SettleFailed { require status == Settled  else reject "not-settled"
                    if attempts < 3 { status' = Allowed } else { status' = Dead } }
  on SettleOk     { require status == Settled  else reject "not-settled"   status' = Done }

  invariant one-decision-per-execution: executed implies (decisions <= 1 || approved)
  step property no-reproposal-after-allow:
    pre.status in { Allowed, Running, Settled } implies post.status != Proposed
  step property no-deny-after-run: pre.executed implies post.status != Denied
  liveness settles: eventually status in { Done, Denied, Dead }
    under fair { Propose, GateAllow | GateDeny | GateEscalate, EscalationTimeout, Start,
                 HandlerOk | HandlerFailed, SettleOk | SettleFailed }
}

